  // privacyPolicy
  "privacyPolicy.atSsaaScheduleSomeoneAnytimeAnywhere": { en: "At SSAA (Schedule Someone Anytime Anywhere), we are committed to protecting your privacy. This Privacy Policy outlines how we collect, use, and protect your information, with specific disclosures regarding our automated SMS messaging program.", es: "En SSAA (Schedule Someone Anytime Anywhere) nos comprometemos a proteger su privacidad. Este Aviso de privacidad describe cómo recopilamos, usamos y protegemos su información, con avisos específicos sobre nuestro programa de mensajes de texto (SMS) automáticos." },
  "privacyPolicy.email": { en: "Email:", es: "Correo electrónico:" },
  "privacyPolicy.furthermoreSellingRentingTransferringOrS": { en: "Furthermore, selling, renting, transferring, or sharing consumer opt-in consent or mobile phone numbers is strictly prohibited. We do not share your mobile information with any third parties or affiliates for marketing or promotional purposes.", es: "Además, está estrictamente prohibido vender, rentar, transferir o compartir el consentimiento de aceptación de los consumidores o sus números de celular. No compartimos su información móvil con terceros ni afiliados para fines de mercadotecnia o promoción." },
  "privacyPolicy.howeverAllTheAboveCategoriesExclude": { en: "However, All the above categories exclude text messaging originator opt-in data and consent; this information won't be shared with any third parties.", es: "Sin embargo, todas las categorías anteriores excluyen los datos y el consentimiento de aceptación de mensajes de texto del remitente; esta información no se compartirá con ningún tercero." },
  "privacyPolicy.ifYouHaveAnyQuestionsOr": { en: "If you have any questions or concerns about this Privacy Policy or how your data is handled, please contact us at:", es: "Si tiene preguntas o inquietudes sobre este Aviso de privacidad o sobre cómo se manejan sus datos, comuníquese con nosotros:" },
  "privacyPolicy.lastUpdated7112026": { en: "Last Updated: 7/11/2026", es: "Última actualización: 11/7/2026" },
  "privacyPolicy.n1InformationWeCollect": { en: "1. Information We Collect", es: "1. Información que recopilamos" },
  "privacyPolicy.n2HowWeUseYourInformation": { en: "2. How We Use Your Information", es: "2. Cómo usamos su información" },
  "privacyPolicy.n3InformationSharingThirdParties": { en: "3. Information Sharing & Third Parties", es: "3. Intercambio de información y terceros" },
  "privacyPolicy.n4Security": { en: "4. Security", es: "4. Seguridad" },
  "privacyPolicy.n5ContactUs": { en: "5. Contact Us", es: "5. Contáctenos" },
  "privacyPolicy.phone": { en: "Phone:", es: "Teléfono:" },
  "privacyPolicy.ssaaPrivacyPolicy": { en: "SSAA Privacy Policy", es: "Aviso de privacidad de SSAA" },
  "privacyPolicy.toBeExplicitlyClearNoMobile": { en: "To be explicitly clear, No mobile information will be shared with third party/affiliates for marketing or promotional purposes.", es: "Para que quede claro: no se compartirá ninguna información móvil con terceros ni afiliados para fines de mercadotecnia o promoción." },
  "privacyPolicy.weCollectInformationThatYouVoluntarily": { en: "We collect information that you voluntarily provide to us when you register for an account or opt-in to our communications. This includes your mobile phone number when you consent to receive automated text messages through the SSAA Text Alert Consent form.", es: "Recopilamos la información que usted nos proporciona voluntariamente al registrarse para una cuenta o aceptar recibir nuestras comunicaciones. Esto incluye su número de celular cuando da su consentimiento para recibir mensajes de texto automáticos mediante el formulario SSAA Text Alert Consent." },
  "privacyPolicy.weImplementStandardSecurityMeasuresTo": { en: "We implement standard security measures to protect the personal information and mobile numbers you provide to us from unauthorized access or disclosure.", es: "Aplicamos medidas de seguridad estándar para proteger contra el acceso o la divulgación no autorizados la información personal y los números de celular que nos proporciona." },
  "privacyPolicy.weMayShareGeneralDataWith": { en: "We may share general data with necessary third-party service providers (such as cloud hosting or payment processors) strictly to operate the SSAA platform.", es: "Podemos compartir datos generales con proveedores de servicios externos necesarios (como hospedaje en la nube o procesadores de pago) estrictamente para operar la plataforma SSAA." },
  "privacyPolicy.weUseYourInformationIncludingYour": { en: "We use your information, including your mobile phone number, specifically to operate our platform and deliver requested services. For our SMS program, this means using your number to send automated text messages regarding schedule requests, confirmations, cancellations, reminders, and important account updates. Your information will not be shared unless it is necessary for the platform to operate. Your information will not be sold, or used by us outside of this platform.", es: "Usamos su información, incluido su número de celular, específicamente para operar nuestra plataforma y prestar los servicios solicitados. En nuestro programa de SMS, esto significa usar su número para enviar mensajes de texto automáticos sobre solicitudes de programación, confirmaciones, cancelaciones, recordatorios y actualizaciones importantes de su cuenta. Su información no se compartirá salvo que sea necesario para el funcionamiento de la plataforma. Su información no se venderá ni la usaremos fuera de esta plataforma." },

