/** Looks up a key; falls back to English, then to the key itself. */
export function getTranslation(
  key: string,
  lang: Language,
  replacements?: Record<string, string | number | null | undefined>,
): string {
  const entry = translations[key];
  if (!entry) return key;
  let text = entry[lang] || entry['en'] || key;
  if (replacements) {
    Object.entries(replacements).forEach(([k, v]) => {
      text = text.split(`{${k}}`).join(v == null ? "" : String(v));
    });
  }
  return text;
}

/** For tooling and tests: every key with both languages. */
export function allTranslations(): Readonly<Record<string, Record<Language, string>>> {
  return translations;
}
